// Fetch shaders are generated by the PS4 driver from the vertex inputs: V# loads from the
// table in the user data (s_load_dwordx4) and buffer_load_format/tbuffer_load_format per
// attribute (separate or interleaved), optionally v_add_i32 of base vertex/instance SGPRs to
// v0/v3, then s_setpc_b64 back. Parsing them recovers the vertex inputs.
#include <array>
#include <cstring>
#include <unordered_map>
#include <vector>

#include "bbport_toggles.h"
#include "common/assert.h"
#include "gcn/decoder.h"
#include "shader/frontend/fetch_shader.h"
#include "shader/frontend/instruction.h"

namespace Shader::Gcn {

const u32* GetFetchShaderCode(const Info& info, u32 sgpr_base) {
    const u32* code;
    std::memcpy(&code, &info.UserData()[sgpr_base], sizeof(code));
    if (guest_read_hook) {
        guest_read_hook(code, 0);
    }
    return code;
}

namespace {

bool IsTypedBufferLoad(Opcode op) {
    return op == Opcode::TBUFFER_LOAD_FORMAT_X || op == Opcode::TBUFFER_LOAD_FORMAT_XY ||
           op == Opcode::TBUFFER_LOAD_FORMAT_XYZ || op == Opcode::TBUFFER_LOAD_FORMAT_XYZW;
}

FetchShaderData Parse(const u32* code, const u32*& end) {
    FetchShaderData data{};
    // Where each SGPR quad's V# was loaded from.
    struct VsharpLoad {
        u32 dword_offset{};
        u32 base_sgpr{};
    };
    std::array<VsharpLoad, 104> loads{};
    u32 semantic = 0;
    const u32* pc = code;
    while (true) {
        const auto inst = GcnIsa::Decode(pc);
        data.size += inst.length;
        if (inst.opcode == Opcode::S_SETPC_B64) {
            break;
        }
        if (inst.inst_class == InstClass::ScalarMemRd) {
            loads[inst.dst[0].code] = VsharpLoad{inst.control.smrd.offset, inst.src[0].code * 2};
            continue;
        }
        if (inst.opcode == Opcode::V_ADD_I32) {
            const auto sgpr = s8(inst.src[0].code);
            switch (inst.dst[0].code) {
            case 0:
                data.vertex_offset_sgpr = sgpr;
                break;
            case 3:
                data.instance_offset_sgpr = sgpr;
                break;
            default:
                UNREACHABLE();
            }
        }
        if (inst.inst_class == InstClass::VectorMemBufFmt) {
            // SRSRC counts SGPR quads, SBASE pairs.
            const VsharpLoad& vsharp = loads[inst.src[2].code * 4];
            auto& attrib = data.attributes.emplace_back();
            attrib.semantic = semantic++;
            attrib.dest_vgpr = inst.src[1].code;
            attrib.num_elements = inst.control.mubuf.count;
            attrib.sgpr_base = vsharp.base_sgpr;
            attrib.dword_offset = vsharp.dword_offset;
            attrib.inst_offset = inst.control.mtbuf.offset;
            attrib.instance_data = inst.src[0].code;
            if (IsTypedBufferLoad(inst.opcode)) {
                attrib.data_format = inst.control.mtbuf.dfmt;
                attrib.num_format = inst.control.mtbuf.nfmt;
            }
        }
    }
    end = pc;
    return data;
}

} // namespace

const FetchShaderData* ParseFetchShaderRef(const Shader::Info& info) {
    if (!info.has_fetch_shader) {
        return nullptr;
    }
    const u32* const code = GetFetchShaderCode(info, info.fetch_shader_sgpr_base);

    // bbport: the pipeline lookup parses the fetch shader on every draw; parses are cached per
    // thread by address and checked against a copy of the code (cheaper than decoding).
    struct CachedParse {
        std::vector<u32> code;
        FetchShaderData data;
    };
    thread_local std::unordered_map<const u32*, CachedParse> cache;
    if (const auto it = cache.find(code);
        !BbToggle::Disabled(BbToggle::FetchShaderCache) && it != cache.end() &&
        std::memcmp(code, it->second.code.data(), it->second.code.size() * sizeof(u32)) == 0) {
        return &it->second.data;
    }
    const u32* end;
    FetchShaderData data = Parse(code, end);
    if (cache.size() >= 4096) {
        cache.clear();
    }
    auto& entry = cache[code];
    entry = CachedParse{std::vector<u32>(code, end), std::move(data)};
    return &entry.data;
}

std::optional<FetchShaderData> ParseFetchShader(const Shader::Info& info) {
    if (const FetchShaderData* data = ParseFetchShaderRef(info)) {
        return *data;
    }
    return std::nullopt;
}

} // namespace Shader::Gcn
